    #[test]
    fn html_asset_row_keeps_the_recorded_skip_next_action() {
        let gap = CoverageGap {
            kind: CoverageGapKind::NotTested,
            class: CoverageGapClass::CoverageLoss,
            task_id: Some("task-mcp".into()),
            target_asset_ids: vec!["asset-1".into()],
            dimension: "mcp-armor: not-tested check dimension".into(),
            reason: "This check did not start, so it is not a pass. Diagnostic code: mcp_configuration_absent.".into(),
            next_action_code: NextActionCode::NoActionUnlessScopeChanges,
            next_action: "This project has no MCP configuration to check. Continue with the other checks.".into(),
            unattributed: None,
        };

        let english = html_gap_next_action(
            &gap,
            HtmlReportCatalog::new(crate::export::ReportLocale::En),
        );
        assert_eq!(
            english,
            "This project has no MCP configuration to check. Continue with the other checks."
        );
        assert_ne!(english, "No action for the current scope.");

        let chinese = html_gap_next_action(
            &gap,
            HtmlReportCatalog::new(crate::export::ReportLocale::ZhHant),
        );
        assert_eq!(
            chinese,
            "這個專案沒有可檢查的 MCP 設定；請繼續查看其他檢查。"
        );
        assert!(!chinese.contains("目前範圍不需處理"));
    }

    #[test]
    fn a_clean_cloud_asset_row_names_what_its_check_left_out() {
        let mut case = AssessmentCase::new(
            "Cloud account".into(),
            OrganizationProfile {
                organization_name: "Example Co".into(),
                employee_range: "1-10".into(),
                data_classes: vec![DataClass::General],
                notes: None,
            },
        );
        case.assets.push(Asset {
            id: "asset-aws".into(),
            kind: AssetKind::CloudAccount,
            name: "AWS account 111122223333".into(),
            provider: Some("aws".into()),
            region: None,
            identifiers: vec![],
            discovered_from: vec![],
            candidate: false,
            owner_confirmed: true,
            internet_exposed: None,
            contains_sensitive_data: None,
            metadata: BTreeMap::new(),
        });
        let run: ScanRun = serde_json::from_value(serde_json::json!({
            "id": "run-1",
            "case_id": case.id,
            "sequence": 1,
            "created_at": "2026-10-01T12:00:00Z",
            "completed_at": "2026-10-01T12:05:00Z",
            "knowledge_cutoff": "2026-10-01T12:00:00Z",
            "scope_grant_ids": [],
            "engine_runs": [{
                "id": "task-prowler",
                "scan_run_id": "run-1",
                "engine_id": "prowler",
                "asset_ids": ["asset-aws"],
                "status": "completed",
                "progress_percent": 100,
                "phase": "completed",
                "started_at": "2026-10-01T12:01:00Z",
                "finished_at": "2026-10-01T12:04:00Z",
                "resume_token": null,
                "engine_version": "5.0.0",
                "image_digest": null,
                "rule_version": null,
                "adapter_version": "1",
                "exit_code": 0,
                "raw_artifact_ids": [],
                "error_code": null,
                "error_message": null
            }]
        }))
        .unwrap();
        case.scan_runs.push(run);

        let report = build_beginner_master_report(&case, "run-1").unwrap();
        assert!(report.findings.is_empty());
        for (locale, status, action) in [
            (
                crate::export::ReportLocale::En,
                "No problems in 1 completed check",
                "Run a full Prowler scan of this account (AWS services other than IAM).",
            ),
            (
                crate::export::ReportLocale::ZhHant,
                "1 項已完成檢查未發現問題",
                "請對這個帳號執行完整的 Prowler 掃描（IAM 以外的 AWS 服務）。",
            ),
        ] {
            let catalog = HtmlReportCatalog::new(locale);
            let labels = readable_target_labels(&report, catalog);
            let board = html_asset_result_section(&report, &labels, catalog);
            let row = board
                .split_once("<tr class=\"asset-result asset-result--")
                .and_then(|(_, rest)| rest.split_once("</tr>"))
                .map(|(row, _)| row)
                .expect("the account's row");
            assert!(row.starts_with("no-problems-completed"), "{row}");
            assert!(row.contains(status), "{row}");
            assert!(row.contains(&html_escape(action)), "{row}");
        }
    }

    #[test]
    fn input_profile_rejection_code_wins_over_generic_execution_failure() {
        let checkpoint = ExecutionCheckpoint::from_resume_token(
            &serde_json::json!({
                "case_id": "case-1",
                "scan_run_id": "run-1",
                "engine_run_id": "engine-run-1",
                "engine_id": "grype",
                "attempt": 1,
                "stage": "failed",
                "container_name": null,
                "scope_sha256": null,
                "artifact_ids": [],
                "cleanup_completed": true,
                "last_error": "This check could not read the kind of local input this target provides.",
                "failure_code": "local_input_profile_unsupported"
            })
            .to_string(),
        )
        .expect("classified checkpoint");

        assert_eq!(
            execution_failure_code(&checkpoint).as_deref(),
            Some("local_input_profile_unsupported")
        );
    }

    #[test]
    fn legacy_checkpoint_without_failure_code_stays_a_generic_failure() {
        let checkpoint = ExecutionCheckpoint::from_resume_token(
            &serde_json::json!({
                "case_id": "case-1",
                "scan_run_id": "run-1",
                "engine_run_id": "engine-run-1",
                "engine_id": "grype",
                "attempt": 1,
                "stage": "failed",
                "container_name": null,
                "scope_sha256": null,
                "artifact_ids": [],
                "cleanup_completed": true,
                "last_error": "scanner container exited with status Some(126)"
            })
            .to_string(),
        )
        .expect("legacy checkpoint");

        assert_eq!(checkpoint.failure_code, None);
        assert_eq!(
            execution_failure_code(&checkpoint).as_deref(),
            Some("execution_failed")
        );
    }

    #[test]
    fn every_preflight_diagnostic_is_direct_and_bounded() {
        let reasons = [
            ScanReadinessBlocker::DemoCase,
            ScanReadinessBlocker::ArchivedCase,
            ScanReadinessBlocker::ScanAlreadyActive,
            ScanReadinessBlocker::NoEffectiveScopeGrants,
            ScanReadinessBlocker::NoOwnershipConfirmedTargets,
            ScanReadinessBlocker::NoCompatibleAuthorizedTargets,
            ScanReadinessBlocker::NoRunnableAuthorizedTargets,
            ScanReadinessBlocker::RuntimeUnavailable,
            ScanReadinessBlocker::ProviderSourceRequired,
            ScanReadinessBlocker::ProviderCapabilityUnavailable,
            ScanReadinessBlocker::ProviderSourceAmbiguous,
            ScanReadinessBlocker::ProviderAuthorizationBindingMismatch,
            ScanReadinessBlocker::ProviderTargetBindingMismatch,
            ScanReadinessBlocker::ProviderPreflightUnavailable,
            ScanReadinessBlocker::WorkspaceSnapshotUnavailable,
            ScanReadinessBlocker::EgressGatewayUnavailable,
            ScanReadinessBlocker::EngineExecutionContractInvalid,
            ScanReadinessBlocker::PassiveSourceUnavailable,
            ScanReadinessBlocker::CapturedEvidenceUnavailable,
            ScanReadinessBlocker::ExecutionPreflightUnavailable,
        ];

        for reason in reasons {
            let diagnostic = reason.diagnostic();
            assert!(!diagnostic.is_empty(), "{}", reason.as_str());
            assert!(diagnostic.chars().count() <= 160, "{diagnostic}");
            assert!(!diagnostic.contains("could not"), "{diagnostic}");
            assert!(
                !diagnostic.contains("Other available checks"),
                "{diagnostic}"
            );
            assert!(!diagnostic.contains("right now"), "{diagnostic}");
        }
    }

    struct Fixture {
        directory: tempfile::TempDir,
        storage: Storage,
        engines: EngineRegistry,
        adapters: AdapterRegistry,
    }

    impl Fixture {
        fn new() -> Self {
            Self::with_engines(current_launcher_engine_registry())
        }

        fn with_engines(engines: EngineRegistry) -> Self {
            let directory = tempfile::tempdir().unwrap();
            let storage = Storage::open(directory.path().join("casework.db")).unwrap();
            let adapters = crate::adapters::builtin_adapter_registry().unwrap();
            Self {
                directory,
                storage,
                engines,
                adapters,
            }
        }

        fn service(&self) -> CaseService<'_> {
            CaseService::new(
                &self.storage,
                &self.engines,
                &self.adapters,
                self.directory.path().join("artifacts"),
                self.directory.path().join("signing.key"),
            )
        }

        fn create(&self) -> AssessmentCase {
            self.create_with_intent(None)
        }

        fn create_with_intent(
            &self,
            assessment_intent: Option<AssessmentIntent>,
        ) -> AssessmentCase {
            self.create_with_ai_provenance(assessment_intent, AiGeneratedArtifactAnswer::Unknown)
        }

        fn create_with_ai_provenance(
            &self,
            assessment_intent: Option<AssessmentIntent>,
            ai_generated_artifact: AiGeneratedArtifactAnswer,
        ) -> AssessmentCase {
            self.service()
                .create_case(&CreateCaseRequest {
                    title: "Assessment".into(),
                    organization_name: "Example Co".into(),
                    employee_range: "1-10".into(),
                    assessment_intent,
                    ai_generated_artifact,
                    data_classes: vec![DataClass::General],
                    requested_activities: vec![],
                    source_kinds: vec![],
                    not_applicable_source_kinds: vec![],
                    declared_assets: vec![],
                    notes: None,
                })
                .unwrap()
        }

        fn discovered_asset(&self, case_id: &str, kind: AssetKind) -> (AssessmentCase, Id) {
            if kind == AssetKind::Repository {
                let fixture_id = new_id();
                return self.discovered_repository_with_files(
                    case_id,
                    &[(
                        "src/main.rs",
                        &format!("fn main() {{ println!(\"snapshot fixture {fixture_id}\"); }}\n"),
                    )],
                );
            }
            self.discovered_declared_asset(case_id, kind)
        }

        fn discovered_repository_with_files(
            &self,
            case_id: &str,
            files: &[(&str, &str)],
        ) -> (AssessmentCase, Id) {
            let service = self.service();
            let fixture_id = new_id();
            let selected = self
                .directory
                .path()
                .join("selected-working-trees")
                .join(&fixture_id);
            if files.is_empty() {
                fs::create_dir_all(&selected).unwrap();
            }
            for (relative_path, contents) in files {
                let path = selected.join(relative_path);
                if let Some(parent) = path.parent() {
                    fs::create_dir_all(parent).unwrap();
                }
                fs::write(&path, contents).unwrap();
            }
            fs::create_dir_all(self.directory.path().join("artifacts")).unwrap();
            let snapshot = crate::workspace_snapshot::create_workspace_snapshot(
                self.directory.path().join("artifacts"),
                case_id,
                &format!("workspace-source-{fixture_id}"),
                &selected,
                crate::workspace_snapshot::WorkspaceSnapshotLimits::default(),
            )
            .unwrap();
            let asset_id = snapshot.asset.id.clone();
            let case = service
                .attach_workspace_snapshot(case_id, "Repository snapshot", snapshot)
                .unwrap();
            (case, asset_id)
        }

        fn discovered_repository_without_workspace_snapshot(
            &self,
            case_id: &str,
        ) -> (AssessmentCase, Id) {
            self.discovered_declared_asset(case_id, AssetKind::Repository)
        }

        fn discovered_declared_asset(
            &self,
            case_id: &str,
            kind: AssetKind,
        ) -> (AssessmentCase, Id) {
            let service = self.service();
            let before_ids = service
                .show_case(case_id)
                .unwrap()
                .assets
                .into_iter()
                .map(|asset| asset.id)
                .collect::<BTreeSet<_>>();
            let source = service
                .upsert_source(
                    case_id,
                    SourceMutation {
                        id: None,
                        kind: SourceKind::UserDeclared,
                        label: "Declared scope".into(),
                        status: SourceConnectionStatus::Connected,
                        read_only: true,
                        metadata: BTreeMap::new(),
                    },
                )
                .unwrap();
            let batch = DiscoveryBatch {
                source_id: source.id,
                source_kind: SourceKind::UserDeclared,
                connector_id: "test".into(),
                connector_version: "1".into(),
                observed_at: Utc::now(),
                assets: vec![DiscoveredAsset {
                    observation_key: format!("asset-{}", new_id()),
                    kind,
                    name: "Example asset".into(),
                    provider: None,
                    region: None,
                    stable_identifier: AssetIdentifier {
                        namespace: "example:id".into(),
                        value: new_id(),
                    },
                    additional_identifiers: vec![],
                    internet_exposed: None,
                    contains_sensitive_data: None,
                    metadata: BTreeMap::new(),
                }],
                relations: vec![],
                notices: vec![],
            };
            service.reconcile_discovery_batch(case_id, &batch).unwrap();
            let case = service.show_case(case_id).unwrap();
            let asset_id = case
                .assets
                .iter()
                .find(|asset| !before_ids.contains(&asset.id))
                .expect("declared discovery should add one asset")
                .id
                .clone();
            (case, asset_id)
        }

        fn discovered_aws_accounts(
            &self,
            case_id: &str,
            credential_account_id: &str,
            discovered_account_ids: &[&str],
        ) -> (AssessmentCase, Vec<Id>) {
            let service = self.service();
            let source = service
                .upsert_source(
                    case_id,
                    SourceMutation {
                        id: None,
                        kind: SourceKind::AwsOrganization,
                        label: "AWS organization".into(),
                        status: SourceConnectionStatus::Connected,
                        read_only: true,
                        metadata: BTreeMap::from([(
                            PROVIDER_RESOURCE_SCOPE_METADATA_KEY.into(),
                            Value::String(format!("aws-account:{credential_account_id}")),
                        )]),
                    },
                )
                .unwrap();
            let assets = discovered_account_ids
                .iter()
                .enumerate()
                .map(|(index, account_id)| DiscoveredAsset {
                    observation_key: format!("aws-account-{index}"),
                    kind: AssetKind::CloudAccount,
                    name: format!("AWS account {account_id}"),
                    provider: Some("aws".into()),
                    region: None,
                    stable_identifier: AssetIdentifier {
                        namespace: "aws_account_id".into(),
                        value: (*account_id).into(),
                    },
                    additional_identifiers: vec![],
                    internet_exposed: None,
                    contains_sensitive_data: None,
                    metadata: BTreeMap::new(),
                })
                .collect();
            service
                .reconcile_discovery_batch(
                    case_id,
                    &DiscoveryBatch {
                        source_id: source.id,
                        source_kind: SourceKind::AwsOrganization,
                        connector_id: "aws-organizations-list-accounts".into(),
                        connector_version: "1".into(),
                        observed_at: Utc::now(),
                        assets,
                        relations: vec![],
                        notices: vec![],
                    },
                )
                .unwrap();
            let case = service.show_case(case_id).unwrap();
            let asset_ids = discovered_account_ids
                .iter()
                .map(|account_id| {
                    case.assets
                        .iter()
                        .find(|asset| {
                            asset.identifiers.iter().any(|identifier| {
                                identifier.namespace == "aws_account_id"
                                    && identifier.value == *account_id
                            })
                        })
                        .unwrap()
                        .id
                        .clone()
                })
                .collect();
            (case, asset_ids)
        }

        fn discovered_aws_account(&self, case_id: &str, account_id: &str) -> (AssessmentCase, Id) {
            let (case, asset_ids) =
                self.discovered_aws_accounts(case_id, account_id, &[account_id]);
            assert!(
                !asset_ids.is_empty(),
                "single-account fixture must create an asset"
            );
            (case, asset_ids.into_iter().next().unwrap_or_default())
        }
    }

    fn current_launcher_engine_registry() -> EngineRegistry {
        EngineRegistry::load_builtin().unwrap()
    }

    // Synthetic admission keeps planner properties independent of the current
    // publication state. It never executes or publishes an image.
    fn agentic_test_registry(runnable: bool) -> EngineRegistry {
        let mut entries: Vec<Value> =
            serde_json::from_str(include_str!("../../engines/catalog.json")).unwrap();
        let entry = entries
            .iter_mut()
            .find(|entry| entry["id"] == "agentic-radar")
            .unwrap();
        entry["compatibility"]["runnable"] = Value::Bool(runnable);
        entry["compatibility"]["blocked_by"] = if runnable {
            serde_json::json!([])
        } else {
            serde_json::json!(["Synthetic unavailable image"])
        };
        entry["status"] = serde_json::json!(if runnable {
            "integrated"
        } else {
            "experimental"
        });
        entry["image"] = if runnable {
            serde_json::json!({
                "repository": "ghcr.io/teddashh/ai-security-scanner-engine-agentic-radar",
                "tag": "synthetic-test", "digest": format!("sha256:{}", "1".repeat(64)),
                "signature_identity": null
            })
        } else {
            Value::Null
        };
        EngineRegistry::load_catalog(&serde_json::to_string(&entries).unwrap()).unwrap()
    }

    fn typed_syft_engine_registry(container_command: &[&str]) -> EngineRegistry {
        let mut entries: Vec<Value> =
            serde_json::from_str(include_str!("../../engines/catalog.json")).unwrap();
        let syft = entries
            .iter_mut()
            .find(|entry| entry["id"] == "syft")
            .expect("Syft catalog entry");
        syft["supported_asset_kinds"] = serde_json::json!(["repository", "container_image"]);
        syft["input_contracts"] = serde_json::json!([
            {
                "asset_kind": "repository",
                "input_profile": "repository_working_tree"
            },
            {
                "asset_kind": "container_image",
                "input_profile": "container_image_oci_layout",
                "command": container_command
            }
        ]);
        EngineRegistry::load_catalog(&serde_json::to_string(&entries).unwrap())
            .expect("typed Syft test catalog")
    }

    fn write_empty_test_oci_layout(root: &Path) {
        let blobs = root.join("blobs/sha256");
        fs::create_dir_all(&blobs).unwrap();
        fs::write(
            root.join("oci-layout"),
            br#"{"imageLayoutVersion":"1.0.0"}"#,
        )
        .unwrap();
        let config = serde_json::to_vec(&serde_json::json!({
            "architecture": "amd64",
            "os": "linux",
            "rootfs": {"type": "layers", "diff_ids": []},
            "config": {}
        }))
        .unwrap();
        let config_digest = hex::encode(Sha256::digest(&config));
        fs::write(blobs.join(&config_digest), &config).unwrap();
        let manifest = serde_json::to_vec(&serde_json::json!({
            "schemaVersion": 2,
            "mediaType": "application/vnd.oci.image.manifest.v1+json",
            "config": {
                "mediaType": "application/vnd.oci.image.config.v1+json",
                "digest": format!("sha256:{config_digest}"),
                "size": config.len()
            },
            "layers": []
        }))
        .unwrap();
        let manifest_digest = hex::encode(Sha256::digest(&manifest));
        fs::write(blobs.join(&manifest_digest), &manifest).unwrap();
        fs::write(
            root.join("index.json"),
            serde_json::to_vec(&serde_json::json!({
                "schemaVersion": 2,
                "mediaType": "application/vnd.oci.image.index.v1+json",
                "manifests": [{
                    "mediaType": "application/vnd.oci.image.manifest.v1+json",
                    "digest": format!("sha256:{manifest_digest}"),
                    "size": manifest.len()
                }]
            }))
            .unwrap(),
        )
        .unwrap();
    }

    fn attach_test_oci_snapshot(fixture: &Fixture, case_id: &str) -> Id {
        let source_id = format!("typed-oci-source-{}", new_id());
        let selected = fixture
            .directory
            .path()
            .join("selected-oci-layouts")
            .join(&source_id);
        write_empty_test_oci_layout(&selected);
        fs::create_dir_all(fixture.directory.path().join("artifacts")).unwrap();
        let snapshot = crate::workspace_snapshot::create_workspace_snapshot_with_profile(
            fixture.directory.path().join("artifacts"),
            case_id,
            &source_id,
            &selected,
            crate::workspace_snapshot::WorkspaceInputProfile::ContainerImageOciLayout,
            crate::workspace_snapshot::WorkspaceSnapshotLimits::default(),
        )
        .expect("validated OCI layout snapshot");
        let asset_id = snapshot.asset.id.clone();
        fixture
            .service()
            .attach_workspace_snapshot(case_id, "OCI image", snapshot)
            .unwrap();
        asset_id
    }

