    #[test]
    fn garak_routes_two_models_on_one_host_to_separate_exact_assets_and_refuses_scope_widening() {
        use crate::external_scope::{RatePolicy, TemplatePolicy, TransportProtocol};
        let mut entries: Vec<Value> =
            serde_json::from_str(include_str!("../../engines/catalog.json")).unwrap();
        let entry = entries.iter_mut().find(|e| e["id"] == "garak").unwrap();
        // This fixture tests planning only; the production candidate remains unavailable.
        entry["status"] = serde_json::json!("integrated");
        entry["compatibility"]["runnable"] = Value::Bool(true);
        entry["compatibility"]["blocked_by"] = serde_json::json!([]);
        entry["image"] = serde_json::json!({"repository":"ghcr.io/teddashh/ai-security-scanner-engine-garak",
            "tag":"synthetic-test", "digest":format!("sha256:{}", "1".repeat(64)), "signature_identity":null});
        let fixture = Fixture::with_engines(
            EngineRegistry::load_catalog(&serde_json::to_string(&entries).unwrap()).unwrap(),
        );
        let created = fixture.create();
        let service = fixture.service();
        let mut ids = Vec::new();
        for model in ["fixture/one", "fixture/two"] {
            let input = crate::garak_input::ModelEndpointInput::validated(
                "https://model.example.test:8443/v1/chat/completions",
                model,
            )
            .unwrap();
            let case = service
                .configure_model_endpoint(&created.id, input.clone(), false)
                .unwrap();
            let id = case
                .assets
                .iter()
                .find(|asset| crate::garak_input::asset_input(asset).ok().as_ref() == Some(&input))
                .unwrap()
                .id
                .clone();
            let request = ScopeApprovalRequest {
                asset_id: id.clone(),
                permissions: vec![ScanPermission::ActiveExternalTesting],
                confirmed_by: "Fixture owner".into(),
                expires_at: Some(Utc::now() + Duration::minutes(30)),
                authorization_reference: Some("Controlled fixture with provider charges".into()),
                notes: None,
                external_scope: Some(ExternalScopeRequest {
                    target: "model.example.test".into(),
                    ports: [8443].into_iter().collect(),
                    protocol: TransportProtocol::Https,
                    activity: ExternalActivity::ActiveExternal,
                    rate_policy: RatePolicy {
                        requests_per_second: 1,
                        concurrency: 1,
                        timeout_seconds: 20,
                    },
                    template_policy: TemplatePolicy::conservative_profile(
                        crate::garak_input::SOURCE_REVISION,
                        crate::garak_input::PROFILE_ID,
                    ),
                    asserted_authority: "Controlled fixture with provider charges".into(),
                    allow_sensitive_networks: true,
                }),
            };
            for field in ["rate", "port", "profile", "private"] {
                let mut invalid = request.clone();
                let external = invalid.external_scope.as_mut().unwrap();
                match field {
                    "rate" => external.rate_policy.requests_per_second = 2,
                    "port" => {
                        external.ports.insert(443);
                    }
                    "profile" => external.template_policy.profile_id = Some("other_profile".into()),
                    _ => external.allow_sensitive_networks = false,
                };
                assert!(
                    service.approve_scope(&created.id, invalid).is_err(),
                    "{field}"
                );
            }
            assert_eq!(
                service.show_case(&created.id).unwrap().scope_grants.len(),
                ids.len()
            );
            service.approve_scope(&created.id, request).unwrap();
            ids.push(id);
        }
        let scoped = service.show_case(&created.id).unwrap();
        assert!(!default_plan_includes_manifest(
            &scoped,
            fixture.engines.get("garak").unwrap(),
            &effective_grants(&scoped, Utc::now()),
            Utc::now()
        ));
        let plan = service
            .plan_scan(
                &created.id,
                ScanPlanRequest {
                    engine_ids: vec![],
                    engine_asset_routes: vec![EngineAssetRoute {
                        engine_id: "garak".into(),
                        asset_ids: ids.clone(),
                    }],
                },
            )
            .unwrap();
        assert_eq!(plan.executable.len(), 2);
        assert!(plan.not_executed.is_empty());
        let frozen = plan
            .executable
            .iter()
            .map(|e| {
                assert_eq!(e.assets.len(), 1);
                assert_eq!(e.scope_grants.len(), 1);
                assert_eq!(e.assets[0].id, e.scope_grants[0].asset_id);
                e.assets[0].id.clone()
            })
            .collect::<BTreeSet<_>>();
        assert_eq!(frozen, ids.into_iter().collect());
    }

    #[test]
    fn agentic_inventory_requires_selection_and_freezes_only_its_selected_repository() {
        use crate::agentic_radar_input::{AgenticFramework, selected_framework};
        let fixture = Fixture::with_engines(agentic_test_registry(true));
        let created = fixture.create();
        let (saved, first) = fixture.discovered_asset(&created.id, AssetKind::Repository);
        let sha = saved
            .assets
            .iter()
            .find(|a| a.id == first)
            .unwrap()
            .metadata["workspace_snapshot_sha256"]
            .as_str()
            .unwrap()
            .to_owned();
        let (_, second) = fixture.discovered_asset(&created.id, AssetKind::Repository);
        let service = fixture.service();
        approve_repository_local_artifact_read(&service, &created.id, first.clone());
        approve_repository_local_artifact_read(&service, &created.id, second.clone());
        let request = ScanPlanRequest {
            engine_ids: vec!["agentic-radar".into()],
            engine_asset_routes: vec![],
        };
        let unselected = service.plan_scan(&created.id, request.clone()).unwrap();
        assert!(unselected.executable.is_empty());
        assert_eq!(
            unselected.not_executed[0].reason_code,
            "agentic_framework_unselected"
        );
        service
            .select_agentic_framework(&created.id, &first, &sha, Some(AgenticFramework::Langgraph))
            .unwrap();
        let plan = service.plan_scan(&created.id, request).unwrap();
        assert_eq!(plan.executable.len(), 1);
        assert!(plan.not_executed.is_empty());
        let execution = &plan.executable[0];
        assert_eq!(execution.assets.len(), 1);
        assert_eq!(execution.assets[0].id, first);
        assert_eq!(
            selected_framework(&execution.assets[0]).unwrap(),
            Some(AgenticFramework::Langgraph)
        );
        assert!(
            service
                .select_agentic_framework(
                    &created.id,
                    &first,
                    &sha,
                    Some(AgenticFramework::Autogen)
                )
                .is_err()
        );
        assert_eq!(
            selected_framework(
                service
                    .show_case(&created.id)
                    .unwrap()
                    .assets
                    .iter()
                    .find(|a| a.id == first)
                    .unwrap()
            )
            .unwrap(),
            Some(AgenticFramework::Langgraph)
        );
    }

    #[test]
    fn default_plan_omits_a_check_this_app_version_does_not_include() {
        let fixture = Fixture::with_engines(agentic_test_registry(false));
        let created = fixture.create();
        let (_, asset_id) = fixture.discovered_asset(&created.id, AssetKind::Repository);
        let service = fixture.service();
        approve_repository_local_artifact_read(&service, &created.id, asset_id.clone());

        let radar = fixture
            .engines
            .get("agentic-radar")
            .expect("agentic-radar catalog entry");
        assert!(radar.supported_asset_kinds.contains(&AssetKind::Repository));
        assert!(radar.release_blocker().is_some());
        let saved = service.show_case(&created.id).unwrap();
        let sha = saved
            .assets
            .iter()
            .find(|a| a.id == asset_id)
            .unwrap()
            .metadata["workspace_snapshot_sha256"]
            .as_str()
            .unwrap();
        service
            .select_agentic_framework(
                &created.id,
                &asset_id,
                sha,
                Some(crate::agentic_radar_input::AgenticFramework::Langgraph),
            )
            .unwrap();

        let scoped = service.show_case(&created.id).unwrap();
        let now = Utc::now();
        let effective = effective_grants(&scoped, now);
        assert!(
            !compatible_authorized_assets(&scoped, radar, &effective, now).is_empty(),
            "agentic-radar would otherwise be planned for this repository"
        );

        let plan = service
            .plan_scan(&created.id, ScanPlanRequest::default())
            .unwrap();
        assert!(
            plan.executable
                .iter()
                .all(|execution| execution.manifest.id != "agentic-radar")
        );
        assert!(
            plan.not_executed
                .iter()
                .all(|not_executed| not_executed.engine_id != "agentic-radar")
        );
        assert!(
            plan.scan_run
                .engine_runs
                .iter()
                .all(|engine_run| engine_run.engine_id != "agentic-radar")
        );

        // A durable plan leaves the case with a non-terminal scan run, so the
        // first plan must be cancelled before this same case can be planned
        // again with an explicit request.
        service.cancel_scan(&created.id, &plan.scan_run.id).unwrap();

        let explicit_plan = service
            .plan_scan(
                &created.id,
                ScanPlanRequest {
                    engine_ids: vec!["agentic-radar".into()],
                    engine_asset_routes: Vec::new(),
                },
            )
            .unwrap();
        let skipped = explicit_plan
            .not_executed
            .iter()
            .find(|not_executed| not_executed.engine_id == "agentic-radar")
            .expect("explicit request still records agentic-radar as not executed");
        assert_eq!(skipped.reason_code, "engine_release_unavailable");
    }

    #[test]
    fn default_scan_freezes_catalog_limitations_without_fabricating_engine_target_tasks() {
        let mut entries: Vec<Value> =
            serde_json::from_str(include_str!("../../engines/catalog.json")).unwrap();
        entries
            .iter_mut()
            .find(|entry| entry["id"] == "gitleaks")
            .expect("gitleaks catalog entry")["schema_version"] =
            Value::String("invalid-test-schema".into());
        let engines = EngineRegistry::load_catalog(&serde_json::to_string(&entries).unwrap())
            .expect("one rejected entry is a degraded catalog, not a gate");
        let fixture = Fixture::with_engines(engines);
        let created = fixture.create();
        let (_, asset_id) = fixture.discovered_asset(&created.id, AssetKind::Repository);
        let plan = fixture
            .service()
            .authorize_and_persist_scan_before_execution_preflight(
                &created.id,
                vec![ScopeApprovalRequest {
                    asset_id,
                    permissions: vec![ScanPermission::LocalArtifactRead],
                    confirmed_by: "Repository owner".into(),
                    expires_at: None,
                    authorization_reference: None,
                    notes: None,
                    external_scope: None,
                }],
                ScanPlanRequest::default(),
            )
            .unwrap();

        assert!(
            !plan.executable.is_empty(),
            "admitted siblings must still run"
        );
        assert!(
            plan.scan_run
                .engine_runs
                .iter()
                .all(|task| task.engine_id != "gitleaks"),
            "unknown applicability must not become an assetless engine task"
        );
        assert_eq!(plan.scan_run.engine_admission_issues.len(), 1);
        assert_eq!(
            plan.scan_run.engine_admission_issues[0]
                .engine_id
                .as_deref(),
            Some("gitleaks")
        );
        let mut stored = fixture.service().show_case(&created.id).unwrap();
        close_run_without_execution_for_report_fixture(&mut stored, &plan.scan_run.id);
        let report = build_beginner_master_report(&stored, &plan.scan_run.id).unwrap();
        let admission_gap = report
            .coverage_gaps
            .iter()
            .find(|gap| gap.dimension == "additional packaged checks")
            .expect("run-bound catalog limitation is a beginner coverage gap");
        assert_eq!(
            admission_gap.kind,
            crate::beginner_report::CoverageGapKind::NotTested
        );
        assert!(admission_gap.target_asset_ids.is_empty());
        assert!(!admission_gap.reason.contains("gitleaks"));
        assert!(!admission_gap.reason.contains("engine_contract_invalid"));
    }

