    #[test]
    fn planner_not_executed_reason_codes_are_unique_and_sorted() {
        let mut seen = BTreeSet::new();
        let mut previous = "";
        for code in PLANNER_NOT_EXECUTED_REASON_CODES {
            assert!(seen.insert(*code), "duplicate planner reason {code}");
            assert!(
                *code > previous,
                "planner reasons must stay sorted: {previous} before {code}"
            );
            previous = *code;
        }
        for blocker in [
            ScanReadinessBlocker::NoOwnershipConfirmedTargets,
            ScanReadinessBlocker::WorkspaceSnapshotUnavailable,
            ScanReadinessBlocker::ProviderTargetBindingMismatch,
            ScanReadinessBlocker::EngineExecutionContractInvalid,
        ] {
            assert!(
                PLANNER_NOT_EXECUTED_REASON_CODES.contains(&blocker.as_str()),
                "{}",
                blocker.as_str()
            );
        }
    }

    #[test]
    fn mixed_scan_routes_two_engines_to_disjoint_owned_assets_in_one_run() {
        let fixture = Fixture::new();
        let created = fixture.create();
        let (_, first_asset_id) = fixture.discovered_asset(&created.id, AssetKind::Repository);
        let (_, second_asset_id) = fixture.discovered_asset(&created.id, AssetKind::Repository);
        let service = fixture.service();
        for asset_id in [&first_asset_id, &second_asset_id] {
            service
                .approve_scope(
                    &created.id,
                    ScopeApprovalRequest {
                        asset_id: asset_id.clone(),
                        permissions: vec![ScanPermission::LocalArtifactRead],
                        confirmed_by: "Repository owner".into(),
                        expires_at: None,
                        authorization_reference: None,
                        notes: None,
                        external_scope: None,
                    },
                )
                .unwrap();
        }

        let plan = service
            .plan_scan_for_execution(
                &created.id,
                ScanPlanRequest {
                    engine_ids: Vec::new(),
                    engine_asset_routes: vec![
                        EngineAssetRoute {
                            engine_id: "gitleaks".into(),
                            asset_ids: vec![first_asset_id.clone()],
                        },
                        EngineAssetRoute {
                            engine_id: "semgrep".into(),
                            asset_ids: vec![second_asset_id.clone()],
                        },
                    ],
                },
            )
            .unwrap();

        assert_eq!(plan.executable.len(), 2);
        assert!(plan.not_executed.is_empty());
        let routed = plan
            .executable
            .iter()
            .map(|execution| {
                (
                    execution.manifest.id.as_str(),
                    execution
                        .assets
                        .iter()
                        .map(|asset| asset.id.as_str())
                        .collect::<Vec<_>>(),
                )
            })
            .collect::<BTreeMap<_, _>>();
        assert_eq!(routed["gitleaks"], [first_asset_id.as_str()]);
        assert_eq!(routed["semgrep"], [second_asset_id.as_str()]);
        assert_eq!(plan.scan_run.engine_runs.len(), 2);
        assert!(plan.scan_run.engine_runs.iter().all(|engine_run| {
            let expected = if engine_run.engine_id == "gitleaks" {
                &first_asset_id
            } else {
                &second_asset_id
            };
            engine_run.asset_ids == [expected.clone()]
        }));
    }

    #[derive(Debug, Clone, Copy)]
    enum InvalidMixedEnvironmentStart {
        WrongWebsiteRate,
        WrongWebsiteTemplate,
        WrongDeviceTarget,
        WrongDevicePort,
        WrongDeviceRate,
        WrongDeviceTemplate,
        DeviceRoutedToNuclei,
        WebsiteRoutedToGreenbone,
    }

    struct MixedEnvironmentStart {
        case_id: Id,
        website_asset_id: Id,
        first_device_asset_id: Id,
        second_device_asset_id: Id,
        decisions: Vec<ScopeApprovalRequest>,
        request: ScanPlanRequest,
    }

    fn mixed_environment_start(fixture: &Fixture) -> MixedEnvironmentStart {
        let case = fixture
            .service()
            .create_case(&CreateCaseRequest {
                title: "Mixed IT environment".into(),
                organization_name: "Example Co".into(),
                employee_range: "2-49".into(),
                assessment_intent: Some(AssessmentIntent::InternalItEnvironment),
                ai_generated_artifact: Default::default(),
                data_classes: vec![],
                requested_activities: vec![AssessmentActivity::ActiveExternalVulnerabilityTests],
                source_kinds: vec![],
                not_applicable_source_kinds: vec![],
                declared_assets: vec![
                    DeclaredAssetInput {
                        kind: DeclaredAssetKind::ExternalTarget,
                        value: "portal.example.test".into(),
                        internet_exposed: Some(true),
                        web_service: Some(DeclaredWebServiceInput {
                            protocol: DeclaredWebProtocol::Https,
                            port: 443,
                            path: "/login".into(),
                            scan_profile: None,
                        }),
                        network_service: None,
                        host_scan: None,
                    },
                    DeclaredAssetInput {
                        kind: DeclaredAssetKind::ExternalTarget,
                        value: "10.20.0.8".into(),
                        internet_exposed: Some(false),
                        web_service: Some(DeclaredWebServiceInput {
                            protocol: DeclaredWebProtocol::Https,
                            port: 443,
                            path: "/".into(),
                            scan_profile: Some(DeclaredWebServiceScanProfile::InternalDeviceHttps),
                        }),
                        network_service: None,
                        host_scan: None,
                    },
                    DeclaredAssetInput {
                        kind: DeclaredAssetKind::ExternalTarget,
                        value: "10.20.0.9".into(),
                        internet_exposed: Some(false),
                        web_service: Some(DeclaredWebServiceInput {
                            protocol: DeclaredWebProtocol::Https,
                            port: 8080,
                            path: "/".into(),
                            scan_profile: Some(DeclaredWebServiceScanProfile::InternalDeviceHttps),
                        }),
                        network_service: None,
                        host_scan: None,
                    },
                ],
                notes: None,
            })
            .unwrap();
        let asset_id = |origin: &str| {
            case.assets
                .iter()
                .find(|asset| {
                    asset
                        .metadata
                        .get(DECLARED_WEB_ORIGIN_METADATA_KEY)
                        .and_then(Value::as_str)
                        == Some(origin)
                })
                .unwrap_or_else(|| panic!("missing declared service {origin}"))
                .id
                .clone()
        };
        let website_asset_id = asset_id("https://portal.example.test:443");
        let first_device_asset_id = asset_id("https://10.20.0.8:443");
        let second_device_asset_id = asset_id("https://10.20.0.9:8080");
        let scope_decision =
            |asset_id: &str, external_scope: ExternalScopeRequest| ScopeApprovalRequest {
                asset_id: asset_id.into(),
                permissions: vec![ScanPermission::ActiveExternalTesting],
                confirmed_by: "Target owner".into(),
                expires_at: Some(Utc::now() + Duration::hours(1)),
                authorization_reference: Some("Approved mixed environment scan".into()),
                notes: None,
                external_scope: Some(external_scope),
            };
        let device_scope = |target: &str, port: u16, profile: DeclaredWebServiceScanProfile| {
            ExternalScopeRequest {
                target: target.into(),
                ports: BTreeSet::from([port]),
                protocol: crate::external_scope::TransportProtocol::Https,
                activity: ExternalActivity::ActiveExternal,
                rate_policy: crate::external_scope::RatePolicy {
                    requests_per_second: 2,
                    concurrency: 1,
                    timeout_seconds: 15,
                },
                template_policy: crate::external_scope::TemplatePolicy::conservative(
                    INTERNAL_DEVICE_TEMPLATE_REVISION,
                    internal_device_profile_oids(profile)
                        .into_iter()
                        .map(str::to_owned)
                        .collect(),
                ),
                asserted_authority: "Approved exact internal device endpoint".into(),
                allow_sensitive_networks: true,
            }
        };
        let decisions = vec![
            scope_decision(
                &website_asset_id,
                ExternalScopeRequest {
                    target: "portal.example.test".into(),
                    ports: BTreeSet::from([443]),
                    protocol: crate::external_scope::TransportProtocol::Https,
                    activity: ExternalActivity::ActiveExternal,
                    rate_policy: crate::external_scope::RatePolicy {
                        requests_per_second: 10,
                        concurrency: 5,
                        timeout_seconds: 10,
                    },
                    template_policy: crate::external_scope::TemplatePolicy::conservative_profile(
                        DECLARED_WEBSITE_TEMPLATE_REVISION,
                        NUCLEI_WEB_SAFE_PROFILE_ID,
                    ),
                    asserted_authority: "Approved exact public website origin".into(),
                    allow_sensitive_networks: false,
                },
            ),
            scope_decision(
                &first_device_asset_id,
                device_scope(
                    "10.20.0.8",
                    443,
                    DeclaredWebServiceScanProfile::InternalDeviceHttps,
                ),
            ),
            scope_decision(
                &second_device_asset_id,
                device_scope(
                    "10.20.0.9",
                    8080,
                    DeclaredWebServiceScanProfile::InternalDeviceHttps,
                ),
            ),
        ];
        let request = ScanPlanRequest {
            engine_ids: Vec::new(),
            engine_asset_routes: vec![
                EngineAssetRoute {
                    engine_id: "nuclei".into(),
                    asset_ids: vec![website_asset_id.clone()],
                },
                EngineAssetRoute {
                    engine_id: "greenbone".into(),
                    asset_ids: vec![
                        first_device_asset_id.clone(),
                        second_device_asset_id.clone(),
                    ],
                },
            ],
        };
        MixedEnvironmentStart {
            case_id: case.id,
            website_asset_id,
            first_device_asset_id,
            second_device_asset_id,
            decisions,
            request,
        }
    }

    fn assert_invalid_mixed_environment_start_fails_before_persist(
        invalid: InvalidMixedEnvironmentStart,
    ) {
        let fixture = Fixture::new();
        let mut start = mixed_environment_start(&fixture);
        match invalid {
            InvalidMixedEnvironmentStart::WrongWebsiteRate => {
                start.decisions[0]
                    .external_scope
                    .as_mut()
                    .unwrap()
                    .rate_policy
                    .requests_per_second = 4;
            }
            InvalidMixedEnvironmentStart::WrongWebsiteTemplate => {
                start.decisions[0]
                    .external_scope
                    .as_mut()
                    .unwrap()
                    .template_policy
                    .profile_id = Some("nuclei_web_safe_v2".into());
            }
            InvalidMixedEnvironmentStart::WrongDeviceTarget => {
                start.decisions[2].external_scope.as_mut().unwrap().target = "10.20.0.10".into();
            }
            InvalidMixedEnvironmentStart::WrongDevicePort => {
                start.decisions[2].external_scope.as_mut().unwrap().ports = BTreeSet::from([8443]);
            }
            InvalidMixedEnvironmentStart::WrongDeviceRate => {
                start.decisions[2]
                    .external_scope
                    .as_mut()
                    .unwrap()
                    .rate_policy
                    .requests_per_second = 3;
            }
            InvalidMixedEnvironmentStart::WrongDeviceTemplate => {
                start.decisions[2]
                    .external_scope
                    .as_mut()
                    .unwrap()
                    .template_policy
                    .allowed_template_ids
                    .pop();
            }
            InvalidMixedEnvironmentStart::DeviceRoutedToNuclei => {
                start.request.engine_asset_routes = vec![
                    EngineAssetRoute {
                        engine_id: "nuclei".into(),
                        asset_ids: vec![
                            start.website_asset_id.clone(),
                            start.first_device_asset_id.clone(),
                        ],
                    },
                    EngineAssetRoute {
                        engine_id: "greenbone".into(),
                        asset_ids: vec![start.second_device_asset_id.clone()],
                    },
                ];
            }
            InvalidMixedEnvironmentStart::WebsiteRoutedToGreenbone => {
                start.request.engine_asset_routes = vec![EngineAssetRoute {
                    engine_id: "greenbone".into(),
                    asset_ids: vec![
                        start.website_asset_id.clone(),
                        start.first_device_asset_id.clone(),
                        start.second_device_asset_id.clone(),
                    ],
                }];
            }
        }

        let error = fixture
            .service()
            .authorize_and_persist_scan_before_execution_preflight(
                &start.case_id,
                start.decisions,
                start.request,
            )
            .unwrap_err();
        assert!(
            matches!(error, AppError::NotAuthorized(_)),
            "{invalid:?} should fail closed at the authorization or route boundary: {error}"
        );
        let stored = fixture.service().show_case(&start.case_id).unwrap();
        assert!(
            stored.scan_runs.is_empty(),
            "{invalid:?} persisted a run that could reach launcher preflight"
        );
        assert!(
            stored.scope_grants.is_empty(),
            "{invalid:?} persisted authorization from a rejected atomic Start"
        );
    }

    #[test]
    fn zap_website_profile_is_exact_and_cannot_authorize_a_device() {
        let fixture = Fixture::new();
        let start = mixed_environment_start(&fixture);
        let case = fixture.service().show_case(&start.case_id).unwrap();
        let website = case
            .assets
            .iter()
            .find(|asset| asset.id == start.website_asset_id)
            .unwrap();
        let device = case
            .assets
            .iter()
            .find(|asset| asset.id == start.first_device_asset_id)
            .unwrap();
        let mut external = start
            .decisions
            .iter()
            .find(|decision| decision.asset_id == website.id)
            .unwrap()
            .external_scope
            .clone()
            .unwrap();
        external.rate_policy.requests_per_second = 5;
        external.template_policy = crate::external_scope::TemplatePolicy::conservative_profile(
            crate::zap_work_plan::ZAP_PASSIVE_TEMPLATE_REVISION,
            ZAP_PASSIVE_PROFILE_ID,
        );
        validate_declared_web_service_scope(website, &external).unwrap();
        assert!(validate_declared_web_service_scope(device, &external).is_err());
        for variation in 0..6 {
            let mut changed = external.clone();
            match variation {
                0 => changed.rate_policy.requests_per_second = 6,
                1 => changed.ports.insert(8443).then_some(()).unwrap(),
                2 => changed.template_policy.allow_file_upload = true,
                3 => changed.template_policy.revision = DECLARED_WEBSITE_TEMPLATE_REVISION.into(),
                4 => changed.rate_policy.timeout_seconds = 11,
                _ => changed.template_policy.profile_id = Some(NUCLEI_WEB_SAFE_PROFILE_ID.into()),
            }
            assert!(validate_declared_web_service_scope(website, &changed).is_err());
        }
    }

    #[test]
    fn zap_and_nuclei_grants_on_a_website_never_cross_engine_routes() {
        let fixture = Fixture::new();
        let mut start = mixed_environment_start(&fixture);
        let website_decision = start
            .decisions
            .iter_mut()
            .find(|decision| decision.asset_id == start.website_asset_id)
            .unwrap();
        let old_nuclei_decision = website_decision.clone();
        let external = website_decision.external_scope.as_mut().unwrap();
        external.rate_policy.requests_per_second = 5;
        external.template_policy = crate::external_scope::TemplatePolicy::conservative_profile(
            crate::zap_work_plan::ZAP_PASSIVE_TEMPLATE_REVISION,
            ZAP_PASSIVE_PROFILE_ID,
        );
        start
            .request
            .engine_asset_routes
            .iter_mut()
            .find(|route| route.engine_id == "nuclei")
            .unwrap()
            .engine_id = ZAP_ENGINE_ID.into();
        let service = fixture.service();
        let first_plan = service
            .authorize_and_persist_scan_before_execution_preflight(
                &start.case_id,
                start.decisions,
                start.request,
            )
            .unwrap();
        let zap_execution = first_plan
            .executable
            .iter()
            .find(|execution| execution.manifest.id == ZAP_ENGINE_ID)
            .unwrap();
        assert_eq!(zap_execution.assets.len(), 1);
        assert_eq!(zap_execution.assets[0].id, start.website_asset_id);
        assert_eq!(zap_execution.scope_grants.len(), 1);
        let zap_grant = zap_execution.scope_grants[0].clone();
        let zap_grant_id = zap_grant.id.clone();
        assert_eq!(
            first_plan
                .scan_run
                .engine_runs
                .iter()
                .find(|task| task.id == zap_execution.engine_run_id)
                .unwrap()
                .execution_scope_grant_ids,
            Some(vec![zap_grant_id.clone()])
        );
        let mut case = service.show_case(&start.case_id).unwrap();
        case.scan_runs.clear();
        fixture
            .storage
            .save_case(&mut case, "test.finish_zap_plan")
            .unwrap();
        service
            .approve_scope(&case.id, old_nuclei_decision)
            .unwrap();
        // Imported legacy cases may retain several independently identified
        // grants. A fresh approval deliberately replaces its permission.
        let mut mixed = service.show_case(&case.id).unwrap();
        let nuclei_grant = mixed
            .scope_grants
            .iter_mut()
            .find(|grant| grant.id == zap_grant_id)
            .unwrap();
        nuclei_grant.id = new_id();
        nuclei_grant.external_scope.as_mut().unwrap().id = nuclei_grant.id.clone();
        mixed.scope_grants.push(zap_grant);
        fixture
            .storage
            .save_case(&mut mixed, "test.legacy_profile_grants")
            .unwrap();
        let second = service
            .plan_scan(
                &case.id,
                ScanPlanRequest {
                    engine_ids: vec![],
                    engine_asset_routes: vec![
                        EngineAssetRoute {
                            engine_id: "nuclei".into(),
                            asset_ids: vec![start.website_asset_id.clone()],
                        },
                        EngineAssetRoute {
                            engine_id: ZAP_ENGINE_ID.into(),
                            asset_ids: vec![start.website_asset_id],
                        },
                    ],
                },
            )
            .unwrap();
        assert_eq!(second.executable.len(), 2);
        for execution in second.executable {
            assert_eq!(execution.scope_grants.len(), 1);
            let profile = execution.scope_grants[0]
                .external_scope
                .as_ref()
                .unwrap()
                .template_policy
                .profile_id
                .as_deref();
            if execution.manifest.id == ZAP_ENGINE_ID {
                assert_eq!(execution.scope_grants[0].id, zap_grant_id);
                assert_eq!(profile, Some(ZAP_PASSIVE_PROFILE_ID));
            } else {
                assert_eq!(profile, Some(NUCLEI_WEB_SAFE_PROFILE_ID));
            }
        }
    }

    #[test]
