    fn html_quoted_values(html: &str, open: &str) -> Vec<String> {
        let mut values = Vec::new();
        let mut rest = html;
        while let Some(start) = rest.find(open) {
            let after = &rest[start + open.len()..];
            let Some(end) = after.find('"') else {
                break;
            };
            values.push(after[..end].to_string());
            rest = &after[end + 1..];
        }
        values
    }

