    #[test]
    fn a_framework_state_this_report_does_not_know_still_explains_itself() {
        use crate::export::ReportLocale;
        let english = HtmlReportCatalog::new(ReportLocale::En);
        let chinese = HtmlReportCatalog::new(ReportLocale::ZhHant);
        let exported = "The frozen answers explicitly identify a non-AI assessment and a non-AI-generated artifact, so references to frameworks that only describe AI systems were not inferred.";

        // A state this report knows is translated, and the English report is
        // still the exporter's own sentence.
        assert_eq!(
            framework_explanation_text("not_applicable_to_declared_context", exported, english),
            exported
        );
        let translated =
            framework_explanation_text("not_applicable_to_declared_context", exported, chinese);
        assert_ne!(translated, exported);
        assert!(translated.contains("AI"));

        // A state added upstream without a translation here prints the
        // exporter's sentence rather than nothing. A framework that reports
        // no coordinates has to say why in either case.
        for catalog in [english, chinese] {
            assert_eq!(
                framework_explanation_text("a_state_added_later", exported, catalog),
                exported
            );
        }
    }

    #[test]
    fn every_control_name_this_project_wrote_itself_has_a_chinese_form() {
        // The packaged catalog carries two kinds of name. Reading it here,
        // rather than restating a list, is what makes this a guard: a control
        // added to NIST CSF or ISO/IEC 27001 without a Chinese short name
        // fails, instead of quietly printing English in a Chinese report.
        const CATALOG: &str = include_str!("../../mappings/control-mappings.json");
        let catalog: serde_json::Value = serde_json::from_str(CATALOG).expect("packaged catalog");
        let controls = catalog["controls"].as_array().expect("controls");
        assert!(!controls.is_empty());

        let mut project_authored = 0usize;
        let mut owner_named = 0usize;
        for control in controls {
            let framework = control["framework"].as_str().expect("framework");
            let title = control["title"].as_str().expect("title");
            match framework {
                "NIST CSF" | "ISO/IEC 27001" => {
                    project_authored += 1;
                    assert!(
                        control_title_zh_hant(title).is_some(),
                        "{framework} {} has no Chinese short name: {title}",
                        control["control_id"],
                    );
                }
                // The owners' own names, and kube-bench's own recommendation
                // titles. Translating these would put words in their mouths.
                _ => {
                    owner_named += 1;
                    assert!(
                        control_title_zh_hant(title).is_none(),
                        "{framework} {} translated a name its owner published: {title}",
                        control["control_id"],
                    );
                }
            }
        }
        assert!(project_authored > 0 && owner_named > 0);
    }
    #[test]
    fn a_long_title_is_abbreviated_rather_than_allowed_to_flood_the_running_head() {
        // Short titles are the user's own words, untouched.
        assert_eq!(running_head_title("Quarterly scan"), "Quarterly scan");

        // A long one is cut, and the cut is visible. A silently shortened
        // title reads as a different report on every page after the cover.
        let long = "A".repeat(200);
        let clamped = running_head_title(&long);
        assert!(
            clamped.ends_with('\u{2026}'),
            "a clamped title did not say it was clamped: {clamped}"
        );
        assert_eq!(clamped.chars().count(), 65);

        // The clamp counts characters, not bytes, so it cannot split a
        // multi-byte character and emit a title the parser rejects.
        let chinese = "座".repeat(200);
        let clamped = running_head_title(&chinese);
        assert_eq!(clamped.chars().count(), 65);
        assert!(clamped.starts_with("座座"));

        // An ellipsis hung off a trailing space reads as a typo.
        let spaced = format!("{} tail", "B".repeat(63));
        assert_eq!(
            running_head_title(&spaced),
            format!("{}\u{2026}", "B".repeat(63))
        );
    }

    #[test]
    fn every_fixed_task_sentence_the_report_model_writes_has_a_chinese_one() {
        // The three sentences the model composes for a task record. Each is
        // printed between a translated label and a translated footnote, so a
        // stored sentence with no arm here is the English in a Chinese record.
        // Held by value, not by pattern: this list is what the model writes,
        // and a sentence reworded on that side has to be reworded here.
        for stored in [
            "One desktop-host TCP connection attempt; no application payload; reachability observation only.",
            "Stored localhost task contract: unsupported. Endpoint observation: unavailable.",
            "Run-bound diagnostic log: unavailable. Redacted diagnostic export: separate.",
        ] {
            let english = HtmlReportCatalog {
                locale: crate::export::ReportLocale::En,
            };
            let chinese = HtmlReportCatalog {
                locale: crate::export::ReportLocale::ZhHant,
            };
            assert_eq!(
                translated_task_sentence(english, stored),
                stored,
                "the English report reworded a stored sentence"
            );
            let named = translated_task_sentence(chinese, stored);
            assert_ne!(named, stored, "no Chinese sentence for: {stored}");
            assert!(
                !named.is_ascii(),
                "the Chinese sentence for {stored} is not Chinese"
            );
        }
        // A sentence from another build is printed as it was stored, in both.
        let stored = "Some other sentence a future build wrote.";
        for locale in [
            crate::export::ReportLocale::En,
            crate::export::ReportLocale::ZhHant,
        ] {
            assert_eq!(
                translated_task_sentence(HtmlReportCatalog { locale }, stored),
                stored
            );
        }
    }

    #[test]
    fn beginner_visible_html_uses_friendly_labels_and_keeps_exact_ids_collapsed() {
        let fixture = Fixture::new();
        let prepared = crate::localhost_quick_scan::prepare_localhost_quick_scan(
            &fixture.storage,
            fixture.engines.manifests(),
            9001,
        )
        .unwrap();
        let mut case = fixture
            .storage
            .get_case(&prepared.prepared.case_id)
            .unwrap();
        let observed = DateTime::parse_from_rfc3339("2026-09-01T12:34:56.123456789Z")
            .unwrap()
            .with_timezone(&Utc);
        let started = observed - Duration::seconds(1);
        let run = case
            .scan_runs
            .iter_mut()
            .find(|run| run.id == prepared.prepared.scan_run_id)
            .unwrap();
        run.completed_at = Some(observed);
        let task = run
            .engine_runs
            .iter_mut()
            .find(|task| task.id == prepared.prepared.engine_run_id)
            .unwrap();
        let target_id = task.asset_ids[0].clone();
        task.status = EngineRunStatus::Completed;
        task.phase = "completed".into();
        task.progress_percent = 100;
        task.started_at = Some(started);
        task.finished_at = Some(observed);
        task.exit_code = Some(0);
        task.cleanup_removed = Some(true);
        task.localhost_tcp_observation = Some(crate::domain::LocalhostTcpObservation {
            outcome: crate::domain::LocalhostTcpOutcome::Reachable,
            observed_at: observed,
        });
        case.status = CaseStatus::ReadyForHandoff;
        case.updated_at = observed;

        let options = ExportOptions {
            redaction: RedactionProfile::None,
            include_raw_artifacts: false,
            locale: crate::export::ReportLocale::En,
        };
        let html = String::from_utf8(
            html_report_bytes(&case, &prepared.prepared.scan_run_id, &options).unwrap(),
        )
        .unwrap();
        let (beginner_visible, technical_details) = html
            .split_once("<details class=\"technical\"")
            .expect("readable report keeps technical details in a separate collapsed section");

        for expected in [
            "Connection test (not a vulnerability scan)",
            "Connection test only",
            "Web service",
            "saved task settings",
            "127.0.0.1:9001",
            "2026-09-01 12:34:56 UTC",
        ] {
            assert!(
                beginner_visible.contains(expected),
                "beginner-visible HTML omitted friendly text {expected}"
            );
        }
        // A framework's own published URL is a verbatim external identifier,
        // not this report's wording, and one of them
        // (cisecurity.org/benchmark/amazon_web_services) contains an asset
        // kind's key as a substring. Checking the wording means checking the
        // wording.
        let reader_wording = {
            let mut kept = String::with_capacity(beginner_visible.len());
            let mut rest = beginner_visible;
            while let Some(at) = rest.find("<span class=\"framework-source__url\">") {
                kept.push_str(&rest[..at]);
                rest = rest[at..]
                    .split_once("</span>")
                    .map(|(_, tail)| tail)
                    .unwrap_or("");
            }
            kept.push_str(rest);
            kept
        };
        for machine_facing in [
            "quick_discovery",
            "web_service",
            "tested_complete",
            "frozen_task_contract",
            target_id.as_str(),
            ".123456789",
            "T12:34:56",
        ] {
            assert!(
                !reader_wording.contains(machine_facing),
                "beginner-visible HTML leaked machine-facing value {machine_facing}"
            );
        }
        assert!(
            technical_details.contains(&target_id),
            "collapsed technical details retain the exact target ID for auditability"
        );
        // The sentence that says this task was not a vulnerability scan.
        assert!(
            technical_details.contains(
                "One desktop-host TCP connection attempt; no application payload; reachability observation only."
            ),
            "the connection test dropped the contract that says what it was not"
        );
        assert!(!html.contains("<details class=\"technical\" open"));
        assert!(html.contains(concat!(
            "Content-Security-Policy\" content=\"default-src 'none'; ",
            "style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"
        )));
        assert!(html.contains("<html lang=\"en\">"));
        assert!(html.contains("What was actually tested"));
        assert!(html.contains("Framework references are informational navigation"));
        let terms_position = html
            .rfind("<footer><h2>Report terms</h2>")
            .expect("report terms stay in the footer");
        let problems_position = html
            .find("<h2>Problems found</h2>")
            .expect("actionable problems render before report terms");
        assert!(problems_position < terms_position);
        assert!(html.contains("Which assets need attention"));
        assert!(html.contains("asset-result--not-tested"));
        // The pill names the state and the step it implies is said once,
        // under the table, rather than on the row that already said it.
        assert!(html.contains("Not tested"));
        assert!(html.contains("choose an applicable security check for this asset"));

        let zh_options = ExportOptions {
            redaction: RedactionProfile::None,
            include_raw_artifacts: false,
            locale: crate::export::ReportLocale::ZhHant,
        };
        fixture
            .storage
            .save_case(&mut case, "test.terminal_localhost_report")
            .unwrap();
        let zh_preview = fixture
            .service()
            .preview_export(
                &case.id,
                &prepared.prepared.scan_run_id,
                CaseExportFormat::Html,
                &zh_options,
            )
            .unwrap();

        case.scan_runs
            .iter_mut()
            .find(|run| run.id == prepared.prepared.scan_run_id)
            .unwrap()
            .case_id = "mismatched-project-id".into();
        let zh_html = String::from_utf8(
            html_report_bytes(&case, &prepared.prepared.scan_run_id, &zh_options).unwrap(),
        )
        .unwrap();

        assert_eq!(zh_preview.locale, crate::export::ReportLocale::ZhHant);
        assert!(!zh_preview.include_raw_evidence);
        assert!(zh_html.contains("所選掃描輪次的專案識別資料不一致；報告資料：專案內所選記錄。"));
        assert!(
            !zh_html.contains(
                "The selected run has an inconsistent project identity. Report data: selected in-project record."
            )
        );
        // Same sentence, in the language the rest of the record is in. A
        // connection test is the one task a reader most needs told plainly
        // that it was not a vulnerability scan.
        assert!(
            zh_html.contains(
                "對桌面主機嘗試一次 TCP 連線；不送出應用層資料；只取得可連線與否的觀察。"
            ),
            "the connection test's contract stayed in English in the Chinese report"
        );
        assert!(
            !zh_html.contains("reachability observation only"),
            "the English contract is still in the Chinese report"
        );
        for expected in [
            "<html lang=\"zh-Hant\">",
            "哪些資產需要處理",
            "asset-result--not-tested",
            "尚未測試",
            "為這個資產選擇適用的資安檢查，然後開始掃描",
            "實際測試的內容",
            "已完成",
            "框架參照只供資訊導航。",
            "AIDEFEND 參照屬於獨立、非官方的對照",
            "2026年09月01日 12:34:56 UTC",
        ] {
            assert!(
                zh_html.contains(expected),
                "zh-Hant HTML omitted {expected}"
            );
        }
        for english_only in [
            "<html lang=\"en\">",
            "What was actually tested",
            "Framework references are informational navigation",
        ] {
            assert!(
                !zh_html.contains(english_only),
                "zh-Hant HTML retained English catalog text {english_only}"
            );
        }

        let canonical = String::from_utf8(
            canonical_json_bytes(&case, &prepared.prepared.scan_run_id, &options).unwrap(),
        )
        .unwrap();
        for canonical_value in [
            "connection_diagnostic",
            "web_service",
            "tested_complete",
            "frozen_task_contract",
            target_id.as_str(),
        ] {
            assert!(
                canonical.contains(canonical_value),
                "canonical JSON unexpectedly changed {canonical_value}"
            );
        }
    }

    #[test]
    fn shared_safety_advice_is_said_once_and_a_findings_own_advice_stays_on_its_card() {
        const OWN_ADVICE: &str = "Snapshot the cluster admission configuration first.";
        let fixture = Fixture::new();
        let mut case = fixture.create();
        let now = Utc::now();
        case.scan_runs.push(ScanRun {
            id: "run-1".into(),
            case_id: case.id.clone(),
            sequence: 1,
            created_at: now,
            completed_at: Some(now),
            request_outcome: None,
            report_asset_snapshots: Vec::new(),
            knowledge_cutoff: now,
            ai_system_applicable: false,
            ai_system_applicability: Default::default(),
            ai_generated_artifact: Default::default(),
            verification_baseline_run_id: None,
            scope_grant_ids: vec![],
            scope_grant_snapshots: vec![],
            engine_admission_issues: Vec::new(),
            engine_runs: vec![],
        });
        for (id, advice) in [
            ("finding-shared", crate::finding_narrative::ENGLISH_ROLLBACK),
            ("finding-own", OWN_ADVICE),
        ] {
            case.findings.push(Finding {
                family: None,
                severity_basis_code: None,
                confidence_basis_code: None,
                context_factors: Vec::new(),
                id: id.into(),
                case_id: case.id.clone(),
                first_seen_run_id: "run-1".into(),
                last_seen_run_id: "run-1".into(),
                fingerprint: format!("{id}:rule"),
                title: format!("Problem {id}"),
                plain_language_summary: "Independent canonical record".into(),
                possible_impact: "Requires human review".into(),
                severity: Severity::Medium,
                confidence: Confidence::High,
                priority: 50,
                priority_reasons: vec![],
                asset_ids: vec!["asset-1".into()],
                evidence: vec![Evidence {
                    id: format!("evidence-{id}"),
                    finding_id: id.into(),
                    run_id: "run-1".into(),
                    engine_run_id: None,
                    kind: EvidenceKind::Configuration,
                    engine_id: "kubescape".into(),
                    scanner_details: None,
                    source_rule: None,
                    result_pointer_sha256: None,
                    observed_at: now,
                    summary: format!("Independent evidence for {id}"),
                    location: None,
                    artifact_id: format!("artifact-{id}"),
                    artifact_sha256: "a".repeat(64),
                    pointer: Some(format!("/findings/{id}")),
                    redacted: false,
                }],
                control_references: vec![],
                recommendation: "Review without automatic remediation".into(),
                verification_guidance: "Re-run the responsible engine".into(),
                rollback_considerations: Some(advice.into()),
                official_references: vec![],
                recommended_expert_type: "Security reviewer".into(),
                status: FindingStatus::Unreviewed,
                tags: vec![],
            });
            case.finding_observations.push(FindingObservation {
                id: format!("observation-{id}"),
                run_id: "run-1".into(),
                finding_id: id.into(),
                fingerprint: format!("{id}:rule"),
                asset_ids: vec!["asset-1".into()],
                engine_ids: vec!["kubescape".into()],
                severity: Severity::Medium,
                confidence: Confidence::High,
                evidence_hashes: vec!["a".repeat(64)],
                observed_at: now,
                finding_snapshot: None,
            });
        }
        case.updated_at = now;

        let html = String::from_utf8(
            html_report_bytes(&case, "run-1", &ExportOptions::default()).unwrap(),
        )
        .unwrap();
        // The product-authored sentence every remediable finding carries is
        // advice about making any change. Said once, above the steps.
        assert_eq!(
            html.matches(crate::finding_narrative::ENGLISH_ROLLBACK)
                .count(),
            1
        );
        assert!(html.find("Before changing anything") < html.find(">Problems found</h2>"));
        // Advice written for one finding is about that finding, and stays with
        // it, however many cards there are.
        assert_eq!(html.matches(OWN_ADVICE).count(), 1);
        let own_card = html.find(OWN_ADVICE).expect("the card keeps its advice");
        assert!(own_card > html.find(">Problems found</h2>").expect("problems"));
    }

