    #[test]
    fn signing_in_again_after_live_discovery_keeps_the_preserved_provider_evidence() {
        use crate::connectors::{LIVE_PROVIDER_ARTIFACT_METADATA_KEY, LiveProviderArtifactPage};

        let fixture = Fixture::new();
        let case = fixture.create();
        let service = fixture.service();
        let source = service
            .upsert_source(
                &case.id,
                SourceMutation {
                    id: None,
                    kind: SourceKind::AwsOrganization,
                    label: "AWS account 111122223333".into(),
                    status: SourceConnectionStatus::NotConnected,
                    read_only: true,
                    metadata: BTreeMap::new(),
                },
            )
            .unwrap();
        let verification = |evidence: &str| ProviderVerificationState {
            schema_version: "1.0.0".into(),
            provider: crate::bootstrap::BootstrapProvider::Aws,
            profile:
                crate::source_authorization::ProviderSourceProfile::AwsOrganizationReadOnlySession,
            authentication_method: "fixture_short_lived_session".into(),
            provider_identity: "arn:aws:sts::111122223333:assumed-role/SecurityAudit/session"
                .into(),
            subject_id: "fixture-subject".into(),
            resource_scope: "aws-account:111122223333".into(),
            verified_at: Utc::now(),
            credential_expires_at: Utc::now() + Duration::minutes(60),
            identity_endpoint: "https://sts.amazonaws.com/".into(),
            permission_endpoints: vec!["https://iam.amazonaws.com/".into()],
            required_permissions_verified: vec!["inventory.read".into()],
            prohibited_permissions_denied: vec!["inventory.write".into()],
            provider_request_ids: vec!["fixture-request".into()],
            evidence_sha256: evidence.repeat(64),
        };
        service
            .connect_verified_provider_source(&case.id, &source.id, &verification("a"))
            .unwrap();

        // The first sign-in captured inventory, then the capability expired
        // before the next discovery.
        let observed_at = Utc::now();
        service
            .attach_live_provider_capture(
                &case.id,
                &source.id,
                LiveProviderArtifactSet {
                    schema_version: LIVE_PROVIDER_ARTIFACT_SET_SCHEMA.into(),
                    capture_id: "capture-1".into(),
                    profile: "aws-organizations-list-accounts".into(),
                    operation: "organizations:ListAccounts".into(),
                    observed_at,
                    complete: true,
                    pages: vec![LiveProviderArtifactPage {
                        sequence: 1,
                        operation: "organizations:ListAccounts".into(),
                        http_status: 200,
                        parser_eligible: true,
                        artifact: SnapshotArtifactReference::new(
                            "page-1.json",
                            "page-1",
                            "aws-organizations-list-accounts",
                            observed_at,
                            Some("c".repeat(64)),
                        ),
                    }],
                },
            )
            .unwrap();
        service
            .record_live_provider_discovery_outcome(
                &case.id,
                &source.id,
                LiveProviderDiscoveryOutcome {
                    status: SourceConnectionStatus::NeedsReauthorization,
                    code: "provider_discovery_authorization_missing".into(),
                    message: "reconnect this source before live discovery".into(),
                    complete: false,
                    successful_pages: 0,
                    record_count: 0,
                    notices: vec![],
                    observed_at: Utc::now(),
                },
            )
            .unwrap();
        let expired = service
            .show_case(&case.id)
            .unwrap()
            .data_sources
            .into_iter()
            .find(|candidate| candidate.id == source.id)
            .unwrap();
        assert_eq!(expired.status, SourceConnectionStatus::NeedsReauthorization);

        // Frontend edits still cannot carry the backend-owned keys.
        let error = service
            .upsert_source(
                &case.id,
                SourceMutation {
                    id: Some(source.id.clone()),
                    kind: SourceKind::AwsOrganization,
                    label: expired.label.clone(),
                    status: SourceConnectionStatus::Connected,
                    read_only: true,
                    metadata: expired.metadata.clone(),
                },
            )
            .unwrap_err();
        assert!(matches!(error, AppError::InvalidRequest(_)), "{error}");

        let reconnected = service
            .connect_verified_provider_source(&case.id, &source.id, &verification("b"))
            .unwrap();
        assert_eq!(reconnected.status, SourceConnectionStatus::Connected);
        assert_eq!(
            reconnected.metadata["verification_evidence_sha256"],
            Value::String("b".repeat(64))
        );
        for key in [
            LIVE_PROVIDER_ARTIFACT_METADATA_KEY,
            "ai_security_scanner.live_discovery_capture_phase",
            "ai_security_scanner.live_discovery_outcome",
        ] {
            assert!(reconnected.metadata.contains_key(key), "{key}");
            assert_eq!(
                reconnected.metadata.get(key),
                expired.metadata.get(key),
                "{key}"
            );
        }
        let stored = service
            .show_case(&case.id)
            .unwrap()
            .data_sources
            .into_iter()
            .find(|candidate| candidate.id == source.id)
            .unwrap();
        assert_eq!(stored.status, SourceConnectionStatus::Connected);
        assert_eq!(stored.metadata, reconnected.metadata);
    }

    #[test]
    fn compatible_pinned_engine_produces_a_least_privilege_typed_plan() {
        let fixture = Fixture::new();
        let case = fixture.create();
        let (_, asset_id) = fixture.discovered_asset(&case.id, AssetKind::Repository);
        let service = fixture.service();
        service
            .approve_scope(
                &case.id,
                ScopeApprovalRequest {
                    asset_id,
                    permissions: vec![ScanPermission::LocalArtifactRead],
                    confirmed_by: "Owner".into(),
                    expires_at: None,
                    authorization_reference: None,
                    notes: None,
                    external_scope: None,
                },
            )
            .unwrap();
        let plan = service
            .plan_scan(
                &case.id,
                ScanPlanRequest {
                    engine_ids: vec!["gitleaks".into()],
                    engine_asset_routes: Vec::new(),
                },
            )
            .unwrap();
        assert_eq!(plan.executable.len(), 1);
        assert!(plan.not_executed.is_empty());
        assert_eq!(plan.scan_run.engine_runs[0].status, EngineRunStatus::Queued);
        assert_eq!(plan.scan_run.scope_grant_snapshots.len(), 1);
        assert_eq!(
            plan.scan_run.scope_grant_snapshots[0].id,
            plan.scan_run.scope_grant_ids[0]
        );
        assert!(
            plan.scan_run.engine_runs[0]
                .scope_contract_sha256
                .as_deref()
                .is_some_and(|digest| digest.len() == 64)
        );
        assert_eq!(
            plan.scan_run.engine_runs[0]
                .fingerprint_schema_version
                .as_deref(),
            Some(FINGERPRINT_SCHEMA_VERSION)
        );
        assert!(plan.scan_run.engine_runs[0].mapping_version.is_some());
        assert_eq!(
            plan.scan_run.engine_runs[0]
                .mapping_provenance
                .as_ref()
                .map(|provenance| provenance.mapping_version.as_str()),
            plan.scan_run.engine_runs[0].mapping_version.as_deref()
        );
        assert_eq!(plan.executable[0].scope_grants.len(), 1);
        assert_eq!(
            plan.executable[0].scope_grants[0].permission,
            ScanPermission::LocalArtifactRead
        );
        assert!(plan.scan_run.engine_runs[0].resume_token.is_some());
        assert!(!plan.executable[0].ai_system_applicable);
        assert_eq!(
            plan.scan_run.ai_system_applicability,
            AiSystemApplicabilityAnswer::Unknown
        );
    }

    #[test]
    fn planning_freezes_reported_version_from_the_catalog_manifest() {
        let fixture = Fixture::new();
        let case = fixture.create();
        let (_, asset_id) = fixture.discovered_asset(&case.id, AssetKind::Repository);
        let service = fixture.service();
        service
            .approve_scope(
                &case.id,
                ScopeApprovalRequest {
                    asset_id,
                    permissions: vec![ScanPermission::LocalArtifactRead],
                    confirmed_by: "Owner".into(),
                    expires_at: None,
                    authorization_reference: None,
                    notes: None,
                    external_scope: None,
                },
            )
            .unwrap();
        let plan = service
            .plan_scan(
                &case.id,
                ScanPlanRequest {
                    engine_ids: vec!["trufflehog".into(), "gitleaks".into(), "kube-bench".into()],
                    engine_asset_routes: Vec::new(),
                },
            )
            .unwrap();

        let trufflehog = plan
            .scan_run
            .engine_runs
            .iter()
            .find(|run| run.engine_id == "trufflehog")
            .expect("trufflehog run");
        assert_eq!(trufflehog.status, EngineRunStatus::Queued);
        assert_eq!(
            trufflehog.engine_version.as_deref(),
            Some("source@3ab759fef4bb5935d4fe9ac68b503d05346b8364")
        );
        assert_eq!(trufflehog.reported_version.as_deref(), Some("3.97.0"));

        let gitleaks = plan
            .scan_run
            .engine_runs
            .iter()
            .find(|run| run.engine_id == "gitleaks")
            .expect("gitleaks run");
        assert_eq!(gitleaks.status, EngineRunStatus::Queued);
        assert_eq!(gitleaks.engine_version.as_deref(), Some("8.30.1"));
        assert_eq!(gitleaks.reported_version, None);

        let kube_bench = plan
            .scan_run
            .engine_runs
            .iter()
            .find(|run| run.engine_id == "kube-bench")
            .expect("kube-bench run");
        assert_eq!(kube_bench.status, EngineRunStatus::NotExecuted);
        assert_eq!(
            kube_bench.engine_version.as_deref(),
            Some("source@9f133cb7509ce1dbedfc860e94474588000e25ac")
        );
        assert_eq!(kube_bench.reported_version.as_deref(), Some("0.16.0"));
        assert!(plan.not_executed.iter().any(|skipped| {
            skipped.engine_id == "kube-bench" && skipped.engine_run_id == kube_bench.id
        }));
    }

